spec.rawSql:
SELECT
    AVG(absolute_error) FILTER (
        WHERE model = 'random_forest_v2_completed'
    ) AS "RF MAE",
    AVG(absolute_error) FILTER (
        WHERE model = 'xgboost_v2_completed'
    ) AS "XGB MAE"
FROM bird_activity_predictions
WHERE actual_activity IS NOT NULL
  AND model IN ('random_forest_v2_completed', 'xgboost_v2_completed');

SELECT
    MIN(absolute_error) FILTER (
        WHERE model = 'random_forest_v2_completed'
    ) AS "RF Best",
    MIN(absolute_error) FILTER (
        WHERE model = 'xgboost_v2_completed'
    ) AS "XGB Best"
FROM bird_activity_predictions
WHERE actual_activity IS NOT NULL
  AND model IN ('random_forest_v2_completed', 'xgboost_v2_completed');

SELECT
    MAX(predicted_activity) FILTER (
        WHERE model = 'random_forest_v2_completed'
    ) AS "Random Forest",
    MAX(predicted_activity) FILTER (
        WHERE model = 'xgboost_v2_completed'
    ) AS "XGBoost"
FROM bird_activity_predictions
WHERE predicted_hour = (
    SELECT MAX(predicted_hour)
    FROM bird_activity_predictions
    WHERE model IN ('random_forest_v2_completed', 'xgboost_v2_completed')
);

SELECT
    AVG(absolute_error) FILTER (
        WHERE model = 'random_forest_v2_completed'
    ) AS "RF MAE",
    AVG(absolute_error) FILTER (
        WHERE model = 'xgboost_v2_completed'
    ) AS "XGB MAE"
FROM bird_activity_predictions
WHERE actual_activity IS NOT NULL
  AND model IN ('random_forest_v2_completed', 'xgboost_v2_completed');
